const want = $('Report webhook').first().json.body?.dataset;
const all = $json.items ?? [];
const r4 = (v) => Math.round(v * 10000) / 10000;
const summary = (items) => {
  const batches = items.map((i) => ({ batch: i.batch, score: i.score, rejected: i.rejected === true, total: i.total }));
  const codes = {};
  for (const i of items) for (const [k, v] of Object.entries(i.codes ?? {})) codes[k] = (codes[k] ?? 0) + v;
  const top_codes = Object.entries(codes).map(([code, count]) => ({ code, count })).sort((a, b) => b.count - a.count || (a.code < b.code ? -1 : a.code > b.code ? 1 : 0));
  const avg = batches.length ? r4(batches.reduce((s, b) => s + b.score, 0) / batches.length) : 0;
  const worst = batches.reduce((w, b) => (w === null || b.score < w.score ? b : w), null);
  let trend = '그대로';
  if (batches.length >= 2) { const d = batches.at(-1).score - batches[0].score; trend = d > 0.05 ? '좋아짐' : d < -0.05 ? '나빠짐' : '그대로'; }
  return { count: batches.length, batches, avg_score: avg, worst_batch: worst?.batch ?? null, rejected_batches: batches.filter((b) => b.rejected).length, top_codes, trend };
};
const out = summary(all.filter((i) => !want || i.dataset === want));

out.by_dataset = {};
for (const name of [...new Set(all.map((i) => i.dataset ?? ''))]) {
  const s = summary(all.filter((i) => (i.dataset ?? '') === name));
  out.by_dataset[name] = { count: s.count, avg_score: s.avg_score, worst_batch: s.worst_batch, top_code: s.top_codes[0]?.code ?? null };
}
const names = Object.keys(out.by_dataset);
out.worst_dataset = names.length ? names.reduce((w, n) => (out.by_dataset[n].avg_score < out.by_dataset[w].avg_score ? n : w)) : null;
return [{ json: out }];
